const pal = t3template.instances.palette;
t3template.addControl({ id: 'harmony', label: 'Harmony', type: 'select', options: ['analogous', 'triadic', 'split', 'mono'], default: 'triadic', panel: 'Harmony Set' });
t3template.addControl({ id: 'seed', label: 'Seed', type: 'color', default: '#2A6F97', panel: 'Harmony Set' });
t3template.addControl({ id: 'add', label: 'Add Set', type: 'button', panel: 'Harmony Set', onClick: (t) => {
  const c = t.getValues().controls;
  pal.harmony(c.seed, c.harmony).slice(1).forEach((hex) => pal.addFamily({ name: `${c.harmony} ${hex.slice(1)}`, seed: hex }));
} });
t3template.addToolbarButton('Fix Failing', (t) => t.instances.palette.fix(), { shortcut: 'shift+f', title: 'Fix every failing pair' });
